mapper.select:
SELECT FROM paid_coupon_reservation_batch WHERE request_id IN
#{requestId}
ORDER BY request_id FOR UPDATE

mapper.update:
UPDATE paid_coupon_reservation_batch SET state = 'CLAIMED' WHERE request_id IN
#{requestId}
AND state = 'RESERVED'

mapper.select:
SELECT FROM paid_coupon_reservation_batch WHERE state = 'RESERVED' AND expires_at <= NOW()
AND (expires_at > #{cursorExpiresAt} OR (expires_at = #{cursorExpiresAt} AND request_id > #{cursorRequestId}))
ORDER BY expires_at, request_id LIMIT #{limit}
